#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

bool isSelfCrossing(int* distance, int n) {
    if (n >= 5 &&
        distance[3] == distance[1] &&
        (long long)distance[4] + distance[0] >= distance[2]) {
        return true;
    }
    for (int i = 3; i < n; ++i) {
        if (distance[i] >= distance[i - 2] &&
            distance[i - 3] >= distance[i - 1]) {
            return true;
        }
        if (i >= 5 &&
            distance[i - 4] <= distance[i - 2] &&
            (long long)distance[i] + distance[i - 4] >= distance[i - 2] &&
            distance[i - 1] <= distance[i - 3] &&
            (long long)distance[i - 5] + distance[i - 1] >= distance[i - 3]) {
            return true;
        }
    }
    return false;
}

int main(void) {
    char line[2000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    int capacity = 16, n = 0;
    int* distance = (int*)malloc((size_t)capacity * sizeof(int));

    int value = 0;
    bool in_num = false;
    for (int i = 0; line[i] != '\0'; ++i) {
        char ch = line[i];
        if (ch >= '0' && ch <= '9') {
            value = value * 10 + (ch - '0');
            in_num = true;
        } else if (in_num) {
            if (n == capacity) {
                capacity *= 2;
                distance = (int*)realloc(distance, (size_t)capacity * sizeof(int));
            }
            distance[n++] = value;
            value = 0;
            in_num = false;
        }
    }
    if (in_num) {
        if (n == capacity) {
            capacity *= 2;
            distance = (int*)realloc(distance, (size_t)capacity * sizeof(int));
        }
        distance[n++] = value;
    }

    printf("%s\n", isSelfCrossing(distance, n) ? "true" : "false");
    free(distance);
    return 0;
}

