import java.io.*;
import java.util.*;

class Solution {
    public boolean isSelfCrossing(int[] distance) {
        if (distance.length >= 5 &&
            distance[3] == distance[1] &&
            (long) distance[4] + distance[0] >= distance[2]) {
            return true;
        }
        for (int i = 3; i < distance.length; i++) {
            if (distance[i] >= distance[i - 2] &&
                distance[i - 3] >= distance[i - 1]) {
                return true;
            }
            if (i >= 5 &&
                distance[i - 4] <= distance[i - 2] &&
                (long) distance[i] + distance[i - 4] >= distance[i - 2] &&
                distance[i - 1] <= distance[i - 3] &&
                (long) distance[i - 5] + distance[i - 1] >= distance[i - 3]) {
                return true;
            }
        }
        return false;
    }
}

public class Main {
    static int[] parseArray(String line) {
        int l = line.indexOf('[') + 1;
        int r = line.lastIndexOf(']');
        String inner = line.substring(l, r).replaceAll("[\\[\\]\\s]", "");
        if (inner.isEmpty()) return new int[0];
        String[] parts = inner.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i]);
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int[] distance = parseArray(line);
        System.out.println(new Solution().isSelfCrossing(distance));
    }
}

